import Image from 'next/image'
import Link from 'next/link'
import { ArrowUpRight } from 'lucide-react'

import { cn } from '@/lib/utils'

export type CategoryMosaicItem = {
  id: string
  label: string
  href: string
  image: { src: string; alt: string }
  size?: 'standard' | 'tall' | 'wide'
}

export type CategoryMosaicProps = {
  items: readonly CategoryMosaicItem[]
  title?: string
  description?: string
  labelStyle?: 'card' | 'glass' | 'plain'
  rounded?: boolean
  className?: string
}

export function CategoryMosaic({
  items,
  title,
  description,
  labelStyle = 'card',
  rounded = true,
  className,
}: CategoryMosaicProps) {
  return (
    <section
      className={cn('py-16 md:py-24', className)}
      aria-labelledby={title ? 'category-mosaic-title' : undefined}
    >
      <div className="container">
        {title || description ? (
          <header className="mb-10 max-w-2xl">
            {title ? (
              <h2
                id="category-mosaic-title"
                className="text-3xl font-bold tracking-tight md:text-5xl"
              >
                {title}
              </h2>
            ) : null}
            {description ? (
              <p className="mt-4 text-base leading-7 text-muted-foreground">{description}</p>
            ) : null}
          </header>
        ) : null}

        <div className="grid auto-rows-[220px] gap-4 sm:grid-cols-2 lg:grid-cols-4">
          {items.map((item, index) => {
            const inferredSize = item.size ?? (index < 2 ? 'tall' : 'standard')

            return (
              <Link
                href={item.href}
                key={item.id}
                className={cn(
                  'group relative isolate flex overflow-hidden bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2',
                  rounded && 'rounded-2xl',
                  inferredSize === 'tall' && 'sm:row-span-2',
                  inferredSize === 'wide' && 'sm:col-span-2',
                )}
              >
                <Image
                  src={item.image.src}
                  alt={item.image.alt}
                  fill
                  className="object-cover transition-transform duration-700 group-hover:scale-105"
                  sizes="(min-width: 1024px) 25vw, (min-width: 640px) 50vw, 100vw"
                />
                <span className="absolute inset-0 bg-black/10 transition group-hover:bg-black/25" />
                <span
                  className={cn(
                    'relative m-auto inline-flex items-center gap-2 px-5 py-3 text-xs font-bold uppercase tracking-[0.24em] transition duration-300 group-hover:scale-105',
                    labelStyle === 'card' && 'bg-white text-slate-950 shadow-xl',
                    labelStyle === 'glass' &&
                      'border border-white/30 bg-black/25 text-white backdrop-blur-md',
                    labelStyle === 'plain' && 'text-white drop-shadow-lg',
                    rounded && labelStyle !== 'plain' && 'rounded-lg',
                  )}
                >
                  {item.label}
                  <ArrowUpRight
                    className="h-3.5 w-3.5 opacity-0 transition group-hover:opacity-100"
                    aria-hidden
                  />
                </span>
              </Link>
            )
          })}
        </div>
      </div>
    </section>
  )
}

import type { ReactNode } from 'react'
import Link from 'next/link'
import { ArrowUpRight, Check } from 'lucide-react'

import { cn } from '@/lib/utils'

export type DifferentialsSectionItem = {
  title: string
  description: string
  icon?: ReactNode
  eyebrow?: string
  points?: readonly string[]
}

export type DifferentialsSectionProps = {
  eyebrow?: string
  title: string
  description?: string
  items: readonly DifferentialsSectionItem[]
  variant?: 'cards' | 'numbered' | 'split' | 'spotlight'
  columns?: 2 | 3 | 4
  action?: { label: string; href: string }
  className?: string
}

export function DifferentialsSection({
  eyebrow,
  title,
  description,
  items,
  variant = 'cards',
  columns = 3,
  action,
  className,
}: DifferentialsSectionProps) {
  const dark = variant === 'spotlight'
  const columnsClass = {
    2: 'md:grid-cols-2',
    3: 'md:grid-cols-2 lg:grid-cols-3',
    4: 'md:grid-cols-2 xl:grid-cols-4',
  }[columns]

  return (
    <section
      className={cn(
        'overflow-hidden py-20 md:py-28',
        dark ? 'bg-slate-950 text-white' : 'bg-background',
        className,
      )}
    >
      <div
        className={cn(
          'container',
          variant === 'split' && 'grid gap-12 lg:grid-cols-[.78fr_1.22fr] lg:gap-20',
        )}
      >
        <header
          className={cn(
            'max-w-2xl',
            variant !== 'split' && 'mb-12',
            variant === 'split' && 'h-fit lg:sticky lg:top-28',
          )}
        >
          {eyebrow ? (
            <p className="text-xs font-bold uppercase tracking-[0.24em] text-primary">{eyebrow}</p>
          ) : null}
          <h2 className="mt-4 text-3xl font-bold tracking-tight md:text-5xl">{title}</h2>
          {description ? (
            <p
              className={cn(
                'mt-5 text-base leading-8',
                dark ? 'text-white/60' : 'text-muted-foreground',
              )}
            >
              {description}
            </p>
          ) : null}
          {action ? (
            <Link
              href={action.href}
              className="mt-7 inline-flex items-center gap-2 rounded-sm font-semibold text-primary focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              {action.label}
              <ArrowUpRight className="h-4 w-4" aria-hidden />
            </Link>
          ) : null}
        </header>

        <div
          className={cn(
            variant === 'cards' && `grid gap-5 ${columnsClass}`,
            variant === 'numbered' && 'divide-y border-y',
            variant === 'split' && 'space-y-4',
            variant === 'spotlight' && `grid gap-5 ${columnsClass}`,
          )}
        >
          {items.map((item, index) => (
            <article
              key={`${item.title}-${index}`}
              className={cn(
                'group relative',
                variant === 'cards' &&
                  'rounded-3xl border bg-card p-7 shadow-sm transition duration-300 hover:-translate-y-1 hover:border-primary/40 hover:shadow-xl',
                variant === 'numbered' &&
                  'grid gap-5 py-8 md:grid-cols-[80px_1fr_1.2fr] md:items-start',
                variant === 'split' &&
                  'rounded-3xl border bg-card p-7 transition hover:border-primary/40 hover:shadow-lg md:p-8',
                variant === 'spotlight' &&
                  'isolate overflow-hidden rounded-3xl border border-white/10 bg-white/[0.04] p-7 duration-300 before:absolute before:-right-16 before:-top-16 before:-z-10 before:h-44 before:w-44 before:rounded-full before:bg-primary/10 before:blur-3xl before:transition hover:-translate-y-1 hover:border-primary/40 hover:before:bg-primary/25',
              )}
            >
              {variant === 'numbered' ? (
                <span className="text-sm font-bold tracking-[0.2em] text-primary">
                  {String(index + 1).padStart(2, '0')}
                </span>
              ) : item.icon ? (
                <span
                  className={cn(
                    'mb-6 flex h-12 w-12 items-center justify-center rounded-2xl',
                    dark ? 'bg-white/10 text-primary' : 'bg-primary/10 text-primary',
                  )}
                >
                  {item.icon}
                </span>
              ) : (
                <span className="mb-6 block text-sm font-bold tracking-[0.2em] text-primary">
                  {String(index + 1).padStart(2, '0')}
                </span>
              )}

              <div>
                {item.eyebrow ? (
                  <p
                    className={cn(
                      'text-xs font-bold uppercase tracking-[0.18em]',
                      dark ? 'text-white/45' : 'text-muted-foreground',
                    )}
                  >
                    {item.eyebrow}
                  </p>
                ) : null}
                <h3 className={cn('text-xl font-semibold', item.eyebrow && 'mt-2')}>
                  {item.title}
                </h3>
              </div>

              <div>
                <p
                  className={cn(
                    'leading-7',
                    variant === 'numbered' ? 'text-sm' : 'mt-3 text-sm',
                    dark ? 'text-white/60' : 'text-muted-foreground',
                  )}
                >
                  {item.description}
                </p>
                {item.points?.length ? (
                  <ul className="mt-5 space-y-2">
                    {item.points.map((point) => (
                      <li key={point} className="flex items-start gap-2 text-sm">
                        <Check className="mt-0.5 h-4 w-4 shrink-0 text-primary" aria-hidden />
                        <span className={dark ? 'text-white/70' : 'text-muted-foreground'}>
                          {point}
                        </span>
                      </li>
                    ))}
                  </ul>
                ) : null}
              </div>
            </article>
          ))}
        </div>
      </div>
    </section>
  )
}

import { cn } from '@/lib/utils'

export type StatsGridProps = {
  title?: string
  description?: string
  stats: Array<{ value: string; label: string; detail?: string }>
  columns?: 2 | 3 | 4
  className?: string
}

export function StatsGrid({ title, description, stats, columns = 4, className }: StatsGridProps) {
  const columnClass = {
    2: 'md:grid-cols-2',
    3: 'md:grid-cols-3',
    4: 'md:grid-cols-2 lg:grid-cols-4',
  }[columns]
  return (
    <section
      className={cn('py-16 md:py-24', className)}
      aria-labelledby={title ? 'stats-title' : undefined}
    >
      <div className="container">
        {title ? (
          <h2 id="stats-title" className="text-3xl font-bold tracking-tight md:text-4xl">
            {title}
          </h2>
        ) : null}
        {description ? <p className="mt-3 max-w-2xl text-muted-foreground">{description}</p> : null}
        <dl
          className={cn(
            'mt-10 grid gap-px overflow-hidden rounded-2xl border bg-border',
            columnClass,
          )}
        >
          {stats.map((stat) => (
            <div key={`${stat.value}-${stat.label}`} className="bg-background p-7">
              <dt className="text-sm text-muted-foreground">{stat.label}</dt>
              <dd className="mt-2 text-4xl font-bold tracking-tight text-primary">{stat.value}</dd>
              {stat.detail ? (
                <p className="mt-2 text-sm text-muted-foreground">{stat.detail}</p>
              ) : null}
            </div>
          ))}
        </dl>
      </div>
    </section>
  )
}

'use client'

import Image from 'next/image'
import Link from 'next/link'
import { ArrowRight, Heart, ShoppingBag, Star } from 'lucide-react'

import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'

export type ProductCardVariant = 'classic' | 'minimal' | 'horizontal' | 'overlay'

export type ProductCardItem = {
  id: string
  name: string
  description?: string
  image: { src: string; alt: string }
  href: string
  price?: string
  previousPrice?: string
  badge?: string
  rating?: number
}

export type ProductCardProps = {
  product: ProductCardItem
  variant?: ProductCardVariant
  actionLabel?: string
  showFavorite?: boolean
  onAddToCart?: (product: ProductCardItem) => void
  onFavorite?: (product: ProductCardItem) => void
  className?: string
}

export function ProductCard({
  product,
  variant = 'classic',
  actionLabel = 'Adicionar',
  showFavorite = false,
  onAddToCart,
  onFavorite,
  className,
}: ProductCardProps) {
  const horizontal = variant === 'horizontal'
  const overlay = variant === 'overlay'

  return (
    <article
      className={cn(
        'group relative flex h-full min-w-0 overflow-hidden rounded-3xl bg-card transition-all duration-500',
        variant === 'classic' && 'flex-col border shadow-sm hover:-translate-y-1 hover:shadow-xl',
        variant === 'minimal' && 'flex-col rounded-none border-0 bg-transparent',
        horizontal && 'min-h-56 flex-row border shadow-sm hover:border-primary/40',
        overlay && 'min-h-[420px] flex-col justify-end bg-slate-950 text-white shadow-xl',
        className,
      )}
    >
      <Link
        href={product.href}
        className={cn(
          'relative block overflow-hidden bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring',
          horizontal ? 'min-h-full w-2/5 shrink-0' : 'aspect-[4/5] w-full',
          overlay && 'absolute inset-0 aspect-auto',
        )}
        aria-label={`Ver ${product.name}`}
      >
        <Image
          src={product.image.src}
          alt={product.image.alt}
          fill
          className="object-cover transition-transform duration-700 group-hover:scale-105"
          sizes={horizontal ? '(min-width: 768px) 30vw, 45vw' : '(min-width: 1024px) 25vw, 50vw'}
        />
        {overlay ? (
          <span className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/20" />
        ) : null}
      </Link>

      {product.badge ? (
        <span className="absolute left-4 top-4 z-10 rounded-full bg-background/90 px-3 py-1 text-xs font-bold text-foreground shadow-sm backdrop-blur">
          {product.badge}
        </span>
      ) : null}

      {showFavorite ? (
        <button
          type="button"
          onClick={() => onFavorite?.(product)}
          className="absolute right-4 top-4 z-10 flex h-10 w-10 items-center justify-center rounded-full bg-background/90 text-foreground shadow-sm backdrop-blur transition hover:scale-110 hover:text-primary focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          aria-label={`Favoritar ${product.name}`}
        >
          <Heart className="h-4 w-4" aria-hidden />
        </button>
      ) : null}

      <div
        className={cn(
          'relative z-[1] flex flex-1 flex-col p-5',
          horizontal && 'justify-center p-6',
          overlay && 'justify-end p-7',
          variant === 'minimal' && 'px-0',
        )}
      >
        {product.rating ? (
          <div
            className={cn(
              'mb-2 flex items-center gap-1 text-xs text-muted-foreground',
              overlay && 'text-white/70',
            )}
          >
            <Star className="h-3.5 w-3.5 fill-amber-400 text-amber-400" aria-hidden />
            {product.rating.toFixed(1)}
          </div>
        ) : null}

        <Link
          href={product.href}
          className="w-fit rounded-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          <h3 className="text-lg font-semibold tracking-tight transition-colors group-hover:text-primary">
            {product.name}
          </h3>
        </Link>

        {product.description ? (
          <p
            className={cn(
              'mt-2 line-clamp-2 text-sm leading-6 text-muted-foreground',
              overlay && 'text-white/70',
            )}
          >
            {product.description}
          </p>
        ) : null}

        <div className="mt-5 flex items-end justify-between gap-3">
          <div>
            {product.price ? <strong className="text-lg">{product.price}</strong> : null}
            {product.previousPrice ? (
              <span
                className={cn(
                  'ml-2 text-xs text-muted-foreground line-through',
                  overlay && 'text-white/50',
                )}
              >
                {product.previousPrice}
              </span>
            ) : null}
          </div>

          {onAddToCart ? (
            <Button
              type="button"
              size={horizontal ? 'default' : 'icon'}
              variant={overlay ? 'secondary' : 'default'}
              onClick={() => onAddToCart(product)}
              aria-label={`${actionLabel}: ${product.name}`}
              className="shrink-0 gap-2 rounded-full"
            >
              <ShoppingBag className="h-4 w-4" aria-hidden />
              {horizontal ? actionLabel : <span className="sr-only">{actionLabel}</span>}
            </Button>
          ) : (
            <Link
              href={product.href}
              className="inline-flex items-center gap-1 text-sm font-semibold text-primary"
            >
              Ver <ArrowRight className="h-4 w-4" aria-hidden />
            </Link>
          )}
        </div>
      </div>
    </article>
  )
}

'use client'

import { A11y, Autoplay, Keyboard, Navigation, Pagination } from 'swiper/modules'
import { Swiper, SwiperSlide } from 'swiper/react'

import { useReducedMotion } from '@/components/library/motion/useReducedMotion'
import { cn } from '@/lib/utils'

import { ProductCard, type ProductCardItem, type ProductCardVariant } from './ProductCard'

import 'swiper/css'
import 'swiper/css/navigation'
import 'swiper/css/pagination'

export type ProductCarouselProps = {
  products: ProductCardItem[]
  title?: string
  description?: string
  cardVariant?: ProductCardVariant
  slidesPerView?: 2 | 3 | 4
  autoplayDelay?: number | false
  actionLabel?: string
  showFavorite?: boolean
  onAddToCart?: (product: ProductCardItem) => void
  onFavorite?: (product: ProductCardItem) => void
  className?: string
}

export function ProductCarousel({
  products,
  title,
  description,
  cardVariant = 'classic',
  slidesPerView = 4,
  autoplayDelay = false,
  actionLabel,
  showFavorite,
  onAddToCart,
  onFavorite,
  className,
}: ProductCarouselProps) {
  const reducedMotion = useReducedMotion()

  return (
    <section
      className={cn('overflow-hidden py-16 md:py-24', className)}
      aria-labelledby={title ? 'product-carousel-title' : undefined}
    >
      <div className="container">
        {title || description ? (
          <header className="mb-10 max-w-2xl">
            {title ? (
              <h2
                id="product-carousel-title"
                className="text-3xl font-bold tracking-tight md:text-4xl"
              >
                {title}
              </h2>
            ) : null}
            {description ? (
              <p className="mt-3 text-base leading-7 text-muted-foreground">{description}</p>
            ) : null}
          </header>
        ) : null}

        <Swiper
          modules={[A11y, Autoplay, Keyboard, Navigation, Pagination]}
          navigation
          pagination={{ clickable: true, dynamicBullets: true }}
          keyboard={{ enabled: true }}
          autoplay={
            autoplayDelay && !reducedMotion
              ? { delay: autoplayDelay, pauseOnMouseEnter: true, disableOnInteraction: true }
              : false
          }
          spaceBetween={24}
          slidesPerView={1.12}
          breakpoints={{
            640: { slidesPerView: Math.min(2, slidesPerView) },
            1024: { slidesPerView: Math.min(3, slidesPerView) },
            1280: { slidesPerView },
          }}
          className="!overflow-visible !pb-12"
        >
          {products.map((product) => (
            <SwiperSlide key={product.id} className="h-auto">
              <ProductCard
                product={product}
                variant={cardVariant}
                actionLabel={actionLabel}
                showFavorite={showFavorite}
                onAddToCart={onAddToCart}
                onFavorite={onFavorite}
              />
            </SwiperSlide>
          ))}
        </Swiper>
      </div>
    </section>
  )
}

import type { LucideIcon } from 'lucide-react'
import { ArrowUpRight } from 'lucide-react'

import { cn } from '@/lib/utils'

export type ContactMethod = {
  label: string
  value: string
  href: string
  icon?: LucideIcon
}

export type ContactSplitSectionProps = {
  eyebrow?: string
  title: string
  description?: string
  methods: ContactMethod[]
  socialLinks?: Array<{ label: string; href: string }>
  form: React.ReactNode
  formTitle?: string
  className?: string
}

export function ContactSplitSection({
  eyebrow = 'Vamos conversar',
  title,
  description,
  methods,
  socialLinks = [],
  form,
  formTitle = 'Conte sobre o seu projeto',
  className,
}: ContactSplitSectionProps) {
  return (
    <section className={cn('py-16 md:py-24', className)}>
      <div className="container">
        <div className="overflow-hidden rounded-[2rem] border bg-card shadow-sm">
          <div className="grid lg:grid-cols-[0.85fr_1.15fr]">
            <div className="min-w-0 bg-foreground p-7 text-background md:p-10 lg:p-12">
              <p className="text-sm font-semibold uppercase tracking-[0.18em] text-background/70">
                {eyebrow}
              </p>
              <h2 className="mt-4 text-balance text-3xl font-bold tracking-tight md:text-4xl lg:text-5xl">
                {title}
              </h2>
              {description ? (
                <p className="mt-5 max-w-md leading-7 text-background/70">{description}</p>
              ) : null}

              <address className="mt-10 space-y-3 not-italic">
                {methods.map((method) => {
                  const Icon = method.icon
                  return (
                    <a
                      key={`${method.label}-${method.value}`}
                      href={method.href}
                      className="group flex items-center gap-4 rounded-2xl border border-background/15 p-4 transition hover:bg-background/10"
                    >
                      <span className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-background/10">
                        {Icon ? (
                          <Icon className="size-5" aria-hidden="true" />
                        ) : (
                          <ArrowUpRight className="size-5" />
                        )}
                      </span>
                      <span className="min-w-0">
                        <span className="block text-xs uppercase tracking-wider text-background/55">
                          {method.label}
                        </span>
                        <span className="mt-1 block font-medium [overflow-wrap:anywhere]">
                          {method.value}
                        </span>
                      </span>
                    </a>
                  )
                })}
              </address>

              {socialLinks.length ? (
                <div className="mt-8 flex flex-wrap gap-2">
                  {socialLinks.map((link) => (
                    <a
                      key={link.label}
                      href={link.href}
                      className="rounded-full border border-background/20 px-3 py-1.5 text-sm transition hover:bg-background hover:text-foreground"
                    >
                      {link.label}
                    </a>
                  ))}
                </div>
              ) : null}
            </div>

            <div className="min-w-0 p-7 md:p-10 lg:p-12">
              <h3 className="mb-7 text-2xl font-semibold">{formTitle}</h3>
              {form}
            </div>
          </div>
        </div>
      </div>
    </section>
  )
}

import type { ReactNode } from 'react'
import Image from 'next/image'

import { HoverButton } from '@/components/library/primitives/HoverButton'
import { cn } from '@/lib/utils'

export type BannerImmersiveProps = {
  image: { src: string; alt: string }
  title: string
  eyebrow?: string
  symbol?: ReactNode
  description?: string
  actions?: readonly { label: string; href: string; variant?: 'primary' | 'light' | 'outline' }[]
  align?: 'left' | 'center'
  height?: 'screen' | 'large'
  overlay?: 'light' | 'medium' | 'strong'
  className?: string
}

const overlays = {
  light: 'bg-black/25',
  medium: 'bg-black/45',
  strong: 'bg-black/65',
}

/** Banner fotográfico de tela cheia — sem navbar; combine com um componente de Navbars. */
export function BannerImmersive({
  image,
  title,
  eyebrow,
  symbol,
  description,
  actions = [],
  align = 'center',
  height = 'large',
  overlay = 'medium',
  className,
}: BannerImmersiveProps) {
  return (
    <section
      className={cn(
        'relative isolate overflow-hidden bg-slate-950 text-white',
        height === 'screen' ? 'min-h-screen' : 'min-h-[680px]',
        className,
      )}
      aria-labelledby="banner-immersive-title"
    >
      <Image src={image.src} alt={image.alt} fill priority className="object-cover" sizes="100vw" />
      <div className={cn('absolute inset-0', overlays[overlay])} />
      <div className="absolute inset-x-0 top-0 h-40 bg-gradient-to-b from-black/60 to-transparent" />

      <div
        className={cn(
          'container relative z-10 flex items-center py-20',
          height === 'screen' ? 'min-h-screen' : 'min-h-[680px]',
          align === 'center' ? 'justify-center text-center' : 'justify-start text-left',
        )}
      >
        <div className={cn('max-w-4xl', align === 'center' && 'flex flex-col items-center')}>
          {symbol ? <div className="mb-6 text-white">{symbol}</div> : null}
          {eyebrow ? (
            <p className="mb-4 text-xs font-bold uppercase tracking-[0.25em] text-white/70">
              {eyebrow}
            </p>
          ) : null}
          <h1
            id="banner-immersive-title"
            className="text-5xl font-bold tracking-tight sm:text-6xl lg:text-8xl"
          >
            {title}
          </h1>
          {description ? (
